#include "classroom/whisper_engine.hpp"
#include "whisper.h"
#include <chrono>
#include <stdexcept>
namespace classroom {struct WhisperEngine::Impl{whisper_context*ctx{};};WhisperEngine::WhisperEngine(const Config&c):p_(new Impl),c_(c){whisper_context_params cp=whisper_context_default_params();cp.use_gpu=c.gpu;p_->ctx=whisper_init_from_file_with_params(c.model.c_str(),cp);if(!p_->ctx)throw std::runtime_error("cannot load whisper model: "+c.model);}WhisperEngine::~WhisperEngine(){if(p_->ctx)whisper_free(p_->ctx);}TranscriptEvent WhisperEngine::transcribe(SpeechSegment s){auto a=std::chrono::steady_clock::now();auto p=whisper_full_default_params(WHISPER_SAMPLING_GREEDY);p.language="en";p.translate=false;p.no_timestamps=true;p.print_progress=p.print_realtime=p.print_timestamps=false;p.n_threads=c_.whisper_threads;if(whisper_full(p_->ctx,p,s.samples.data(),(int)s.samples.size())!=0)throw std::runtime_error("whisper inference failed");std::string out;for(int i=0;i<whisper_full_n_segments(p_->ctx);i++)out+=whisper_full_get_segment_text(p_->ctx,i);auto b=std::chrono::steady_clock::now();return{s.sequence,s.start_ms,s.end_ms,out,{},std::chrono::duration<double,std::milli>(b-a).count()};}}
